function send(res,code,body,extra={}){res.writeHead(code,{'Content-Type':'application/json','Access-Control-Allow-Origin':'*','Access-Control-Allow-Headers':'*','Access-Control-Expose-Headers':'content-range','Access-Control-Allow-Methods':'*',...extra});res.end(typeof body==='string'?body:JSON.stringify(body));}
export function start(port){
 return http.createServer((req,res)=>{
  const u=url.parse(req.url,true); const path=u.pathname;
  if(req.method==='OPTIONS') return send(res,204,'');
  if(path==='/__lib') { res.writeHead(200,{'Content-Type':'application/javascript'}); return res.end(fs.readFileSync(UMD)); }
  if(path.startsWith('/auth/v1/token')){ let b=''; req.on('data',d=>b+=d); req.on('end',()=>{ try{
    const p=JSON.parse(b||'{}');
    if(p.grant_type==='password'||u.query.grant_type==='password'||b.includes('password')){
      if(p.email==='test@directksa.com'&&p.password==='Dq7nTest-2026-Riyadh') return send(res,200,SESSION);
      if(p.refresh_token||b.includes('refresh_token')) return send(res,200,SESSION);
      return send(res,400,{error:'invalid_grant',error_description:'Invalid login credentials',msg:'Invalid login credentials'});
    }
    return send(res,200,SESSION);
  }catch(_){ return send(res,200,SESSION); } }); return; }
  if(path==='/auth/v1/user') return send(res,200,SESSION.user);
  if(path==='/auth/v1/logout') return send(res,204,'');
  if(path.startsWith('/auth/v1/recover')) return send(res,200,{});
  if(path.startsWith('/functions/v1/admin-users')){
    let body='';
    req.on('data',c=>body+=c);
    return req.on('end',()=>{
      let p={}; try{p=JSON.parse(body||'{}');}catch(_){}
      const A=p.action;
      if(A==='list') return send(res,200,{users:TABLES.app_users.map(u=>({id:u.id,email:u.email,full_name:u.full_name,role:u.role,active:u.active,must_change_password:u.must_change_password,created_at:u.created_at}))});
      if(A==='create'){ const nu={id:'u-'+(TABLES.app_users.length),email:String(p.email||'').toLowerCase(),full_name:p.full_name||'',role:p.role||'team_member',active:true,created_at:'2026-08-09T00:00:00Z',must_change_password:true,allowed_pages:['today','leads','clients']}; TABLES.app_users.push(nu); return send(res,200,{ok:true,email:nu.email,temp_password:'Riyadh1234!'}); }
      if(A==='set_role'){ const u=TABLES.app_users.find(x=>x.id===p.id); if(u)u.role=p.role; return send(res,200,{ok:true}); }
      if(A==='set_active'){ const u=TABLES.app_users.find(x=>x.id===p.id); if(u)u.active=p.active===true; return send(res,200,{ok:true}); }
      if(A==='reset_password'){ return send(res,200,{ok:true,temp_password:'Jeddah5678@'}); }
      if(A==='clear_must_change') return send(res,200,{ok:true});
      return send(res,200,{error:'unknown'});
    });
  }
  if(path==='/__rpclog') return send(res,200,RPCLOG);
  if(path.startsWith('/storage/v1/object/')){
    // proposal file library: accept uploads, remember paths, serve public URLs
    TABLES.__storage=TABLES.__storage||{};
    const key=decodeURIComponent(path.replace(/^\/storage\/v1\/object\/(public\/)?/,''));
    if(req.method==='POST'||req.method==='PUT'){ let chunks=[]; req.on('data',d=>chunks.push(d)); req.on('end',()=>{ TABLES.__storage[key]=Buffer.concat(chunks).length; send(res,200,{Key:key,Id:'mock-'+Object.keys(TABLES.__storage).length}); }); return; }
    if(req.method==='DELETE'){ let b=''; req.on('data',d=>b+=d); req.on('end',()=>{ try{const p=JSON.parse(b||'{}');(p.prefixes||[]).forEach(x=>delete TABLES.__storage['proposals/'+x]);}catch(_){} send(res,200,[]); }); return; }
    if(req.method==='GET'){ return TABLES.__storage[key]!=null?send(res,200,{size:TABLES.__storage[key]}):send(res,404,{error:'not found'}); }
    return send(res,200,{});
  }
  if(path.startsWith('/rest/v1/rpc/')){
    let body='';
    req.on('data',c=>body+=c);
    return req.on('end',()=>{
      let parsed=null; try{parsed=JSON.parse(body||'{}');}catch(_){}
      const fn=path.replace('/rest/v1/rpc/','');
      RPCLOG.push({fn, keys: parsed?Object.keys(parsed.patch||parsed.payload||{}):[], arg: parsed?Object.keys(parsed):[]});
      send(res,200,{});
    });
  }
  if(path.startsWith('/rest/v1/')){
    const t=path.replace('/rest/v1/','').split('?')[0];
    let rows=TABLES[t]||[];
    if(req.method==='POST'){ let b=''; req.on('data',d=>b+=d); req.on('end',()=>{ try{
      const parsed=JSON.parse(b||'[]'); const list=Array.isArray(parsed)?parsed:[parsed];
      const key=(t==='finance_targets')?'year':'id';
      list.forEach(row=>{ const arr=(TABLES[t]=TABLES[t]||[]);
        if(key==='id'&&row.id==null){ row.id='gen-'+Math.random().toString(36).slice(2,10)+arr.length; arr.push(row); return; }
        const i=arr.findIndex(r=>String(r[key])===String(row[key])); if(i>=0)arr[i]={...arr[i],...row}; else arr.push(row); });
    }catch(_){} send(res,201,[]); }); return; }
    if(req.method==='PATCH'){ let b=''; req.on('data',d=>b+=d); req.on('end',()=>{ try{
      const patch=JSON.parse(b||'{}'); let list=TABLES[t]||[];
      Object.keys(u.query||{}).forEach(k=>{ if(k==='select')return; let val=u.query[k]; if(Array.isArray(val))val=val[0];
        const m=String(val||'').match(/^eq\.(.*)$/); if(m) list=list.filter(r=>String(r[k])===m[1]);
        if(String(val)==='is.null') list=list.filter(r=>r[k]==null); });
      list.forEach(r=>Object.assign(r,patch));
    }catch(_){} send(res,204,[]); }); return; }
    if(req.method!=='GET') return send(res,201,[]);
    // apply simple eq filters from the query string (e.g. id=eq.<uuid>) like real PostgREST,
    // so .eq(...).maybeSingle() returns exactly the matching row (not row[0] of the whole table).
    Object.keys(u.query||{}).forEach(k=>{
      if(k==='select'||k==='order'||k==='limit'||k==='offset')return;
      let val=u.query[k]; if(Array.isArray(val))val=val[0];
      const m=String(val||'').match(/^eq\.(.*)$/);
      if(m){ const want=m[1]; rows=rows.filter(r=>String(r[k])===want); }
    });
    // PostgREST semantics: a Range header windows the result; with or without one,
    // the server never returns more than 1000 rows (Supabase default max-rows).
    // The real bug this catches: .limit(10000) still gets only 1000 back.
    const total=rows.length;
    const qp=k=>{let v=u.query[k];if(Array.isArray(v))v=v[0];return v!=null?parseInt(v,10):null;};
    const rng=String(req.headers.range||'').match(/^(\d+)-(\d+)$/);
    if(rng) rows=rows.slice(+rng[1], +rng[2]+1);
    else { const off=qp('offset')||0, lim=qp('limit');
      if(off||lim!=null) rows=rows.slice(off, lim!=null?off+lim:undefined); }
    if(rows.length>1000) rows=rows.slice(0,1000);
    const single=(req.headers.accept||'').includes('vnd.pgrst.object');
    return send(res,200, single?(rows[0]||null):rows, {'Content-Range':(rng?rng[1]:0)+'-'+Math.max(rows.length-1,0)+'/'+total});
  }
  // Serve a real file if it exists; otherwise fall back to index.html (mirrors the vercel.json
  // SPA rewrite) so deep paths like /leads or /clients and browser reloads work as in production.
  let f=path==='/'?'/index.html':path; let body=null;
  try{ body=fs.readFileSync(APP+f); }
  catch(_){ try{ body=fs.readFileSync(APP+'/index.html'); f='/index.html'; }catch(e){ res.writeHead(404); return res.end('nf'); } }
  res.writeHead(200,{'Content-Type':f.endsWith('.html')?'text/html; charset=utf-8':(f.endsWith('.js')?'application/javascript':'text/plain')}); res.end(body);
 }).listen(port);
}
